      "기존 차트나 예약 프로그램에서 방문 식별과 공개 가능한 안내를 받을 수 있는지 확인합니다. 내부 차트 내용 전체를 환자 화면에 자동 노출하는 방식은 피하고 승인된 자료만 연결해야 합니다. 사진 저장소를 따로 사용하는 경우 파일 접근과 환자 권한이 동일하게 적용되는지 검사합니다. 문자·메신저 연결은 알림 전달 수단이며 담당자의 내용 확인이나 답변 완료를 대신하지 않습니다. 외부 분석 기능을 추가하려면 환자 사진의 전송·저장·학습 사용 조건을 새로 검토해야 합니다. 여기서는 사진 접수·조회와 사람 검토를 기본으로 두고 자동 판독을 연결 가능 기능처럼 단정하지 않습니다."
