      "초기에는 한 기구군과 보관·처리 경로, 실제 담당자 역할로 범위를 좁힐 수 있습니다. 개별 식별·사용·반환·처리·확인·보관의 기록을 연결하고 전문 기준은 기관이 승인한 값과 항목을 사용합니다. 합성 업무 건과 시험 라벨로 다른 기구 오연결·작업 중단·자료 누락·정정을 검수합니다. 장비 연동이 검증되지 않았다면 수동 기록과 확인을 먼저 구현할 수 있지만 그 범위를 명확히 해야 합니다. 인수 기준은 목록에 기구가 보이는 것뿐 아니라 한 사용 사건에서 다음 사용 전 확인까지 이력이 설명되는지입니다. 화면 완료 표시를 실제 안전성 검증으로 과장하지 않습니다."
