      "검사·진료 원본에서 제공할 수 있는 결과값과 문서, 상태·수정 식별을 먼저 확인합니다. 자동 게시를 위해 단순 수신 사건만 사용하는 대신 기관이 승인한 공개 조건을 연결해야 합니다. 본인 확인과 대리 관계는 계정 정보와 실제 의료 자료의 대상 연결을 함께 검증합니다. 예약 시스템과 연결하면 후속 방문 신청과 확정 상태를 구분합니다. 메시지에는 민감한 결과 상세를 불필요하게 담지 않고 현재 권한을 검사하는 조회 경로를 제공하도록 검토합니다. 외부 기관 결과를 가져오는 기능은 출처·단위·버전·제공 범위를 확인해야 하며 표준 형식이라는 이유만으로 모두 같은 항목으로 통합하지 않습니다."
