      "전자의무기록과 실제 계획·시행 상태, 기존 문서 관리 기능을 확인한 뒤 보조 시스템과 최종 원장의 책임을 정합니다. 전자서명 도구를 사용하는 경우 서명 이미지 유무뿐 아니라 대상 문서·주체·시각·변경 탐지 등 실제 지원 범위를 확인해야 합니다. 특정 도구 사용만으로 모든 법적 효력이 보장된다고 설명하지 않습니다. 환자 앱·포털과 연결하면 공개 자료와 내부 확인 메모를 구분하고 현재 권한을 검사합니다. 외부 기관 전달과 문서 출력은 목적·수신자·자료 범위를 연결합니다. 기존 업체가 상태 쓰기를 지원하지 않는 경우 직원 대조·내보내기 범위를 명시하고 자동 반영을 기본 약속으로 하지 않습니다."
