      "통원 환자의 다음 진료와 기관이 승인한 치료 회차를 배정하는 접수·치료실 담당자가 주요 사용자입니다. 환자는 본인에게 공개된 예약 가능 범위 안에서 시간을 선택하거나 변경을 요청합니다. 치료 담당자는 근무·업무 배정과 실제 사용할 공간·장비를 확인하고 의료진은 계획의 변경·중단을 결정합니다. 같은 요일에 반복 방문한다는 이유만으로 모든 회차의 조건이 동일하다고 가정하지 않습니다. 진료와 치료를 같은 날 연결할 필요가 있는지, 특정 담당자의 연속 배정이 필수인지 선호인지부터 확인합니다. 실제 기관이 운영하는 예약 단위를 기준으로 공개 예약과 직원 배정의 경계를 정합니다."
