      "기관의 승인 담당자는 방문 유형·자원·시간 배정·변경 조건과 환자 안내를 정합니다. 예약 직원은 이 기준 안에서 빈 시간과 담당을 확인하고 제안·확정·취소를 처리합니다. 진료·검사·상담 담당자는 자신의 실제 가능 일정과 예외를 확인하며 의료적 분류가 필요한 요청을 별도로 판단합니다. 환자는 승인된 범위에서 가능한 시간을 선택하거나 변경 요청을 남깁니다. 대리 예약자는 허용된 일정 정보에만 접근하고 상담 내용 열람과 구분됩니다. 운영자는 중복 점유·알림·외부 달력 연결 오류를 처리합니다. 어떤 직원이 상세 사유를 볼 수 있는지 예약 권한과 분리하여 정의합니다."
