    "summary": "비뇨기과 검사 예약은 시간표만 채우기보다 환자 준비 상태와 검사 장비·후속 확인의 연결을 함께 설계해야 합니다. 요류 검사와 이후 확인처럼 실제 완료에 따라 다음 단계가 달라지는 업무를 구분하고, 준비 여부나 재검 필요성은 담당자가 판단하도록 구성합니다. 민감한 검사명이 공용 화면과 메시지에 노출되는 범위도 확인합니다.",
